140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        currentOwner.setAddress(ownerFieldsDto.getAddress());
143	        currentOwner.setCity(ownerFieldsDto.getCity());
144	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
145	        currentOwner.setLastName(ownerFieldsDto.getLastName());
146	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
147	        String email = ownerFieldsDto.getEmail();
148	        if (email != null) {
149	            email = email.trim().toLowerCase(Locale.ROOT);
150	            if (!EMAIL_PATTERN.matcher(email).matches()) {
151	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
152	            }
153	        }
154	        currentOwner.setEmail(email);
155	        this.clinicService.saveOwner(currentOwner);
156	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
157	    }
